implementation:
#include <linux/key.h>
#include <linux/errno.h>
#include <linux/uaccess.h>

long read_key_value(key_serial_t keyid, char __user *buffer, size_t buflen) {
    struct key *key = key_lookup(keyid);
    if (IS_ERR(key)) {
        return PTR_ERR(key);
    }

    if (!key_permission(key, KEY_NEED_READ)) {
        key_put(key);
        return -EACCES;
    }

    long ret = -EINVAL;
    struct key_payload payload;

    down_read(&key->sem);
    if (key->type->read) {
        ret = key->type->read(key, &payload);
        if (ret < 0) {
            goto out;
        }

        size_t copy_len = (payload.data[0] < buflen) ? payload.data[0] : buflen;
        if (copy_to_user(buffer, payload.data + 1, copy_len)) {
            ret = -EFAULT;
        } else {
            ret = copy_len;
        }
    }

out:
    up_read(&key->sem);
    key_put(key);
    return ret;
}
